const sensitiveInfoKeys = []; // Define sensitive key parts
const booleanLikeKeys = ["YesNo"];   // Define keys that imply boolean values

return Object.entries(entity)
    .filter(([key, value]) =>
        !key.includes("$$") &&
        !booleanLikeKeys.some(k => key.includes(k)) && // More explicit boolean check
        value
    )
    .map(([key, value]) => {
        const isSensitive = sensitiveInfoKeys.some(k => key.includes(k));
        const isBoolean = typeof value === 'boolean'; // More robust boolean check
        const isArray = Array.isArray(value) && value.length > 0; // Ensure array has elements

        let displayValue;

        if (isSensitive && isArray && typeof value[0] === 'string') {
            displayValue = "*".repeat(value[0].length);
        } else if (isBoolean) {
            displayValue = value ? "YES" : "NO";
        } else if (isArray) {
            displayValue = value[0];
        } else if (isSensitive && typeof value === 'string') {
            displayValue = "*".repeat(value.length);
        } else {
            displayValue = value;
        }

        const formattedKey = this.formatKeyForDisplay(key);
        return { key: formattedKey, value: displayValue }; // Use the formatted key
    });

const SPECIAL_CASES = {
    "pipelinestage": "PipelineStage"
};

const pascalCaseEntity = snakeToPascalCase(entity);
return `${entity}_${operation}${pascalCaseEntity}`;

function snakeToPascalCase(str) {
    if (SPECIAL_CASES[str]) {
        return SPECIAL_CASES[str];
    }

    if (!str || !str.includes('_')) {
        return str.charAt(0).toUpperCase() + str.slice(1);
    }

    return str.split('_')
        .map(word => word.charAt(0).toUpperCase() + word.slice(1))
        .join('');
}

if (typeof form !== 'object' || form === null) {
    console.error("Invalid input: Expected a form object.");
    return;
}

for (const key in form) {
    if (form.hasOwnProperty(key)) {
        const value = form[key];
        if (typeof value === 'object' && value !== null && value.constructor !== Date) {
            this.clearForm(value);
        } else if (value instanceof Date) {
            form[key] = undefined;
        } else {
            form[key] = undefined;
        }
    }
}

if (!form || typeof form !== 'object') {
    console.warn('populateForm: Form is null or undefined.');
    return;
}

const entity = currentEntity || {};
defaultValue = defaultValue ?? null;

/**
 * Helper to search for a key within an entity (directly or inside nested objects).
 */
const getEntityValue = (obj, targetKey) => {
    if (!obj || typeof obj !== 'object') return undefined;

    // Direct match on current level
    if (Object.prototype.hasOwnProperty.call(obj, targetKey)) {
        return obj[targetKey];
    }

    // Search within nested objects
    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key) &&
            typeof obj[key] === 'object' &&
            obj[key] !== null) {
            const found = getEntityValue(obj[key], targetKey);
            if (found !== undefined) return found;
        }
    }

    return undefined;
};

// Iterate through all keys defined on the form
for (const formKey in form) {
    if (Object.prototype.hasOwnProperty.call(form, formKey)) {
        const formValue = form[formKey];

        // If the form field is a nested object (and not an Array/Date), recurse
        if (typeof formValue === 'object' &&
            formValue !== null &&
            !Array.isArray(formValue) &&
            !(formValue instanceof Date)) {
            this.populateForm(formValue, entity, defaultValue);
        } else {
            // Look up value in currentEntity
            const entityValue = getEntityValue(entity, formKey);

            // Assign entity value if present and non-null/undefined, otherwise reset to defaultValue
            if (entityValue !== undefined && entityValue !== null) {
                form[formKey] = entityValue;
            } else {
                form[formKey] = defaultValue;
            }
        }
    }
}

const now = new Date();

const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0'); // Month is 0-indexed
const day = String(now.getDate()).padStart(2, '0');
const hours = String(now.getHours()).padStart(2, '0');
const minutes = String(now.getMinutes()).padStart(2, '0');
const seconds = String(now.getSeconds()).padStart(2, '0');

// Get the timezone offset in minutes
const offsetMinutes = now.getTimezoneOffset();
const offsetHours = String(Math.abs(Math.floor(offsetMinutes / 60))).padStart(2, '0');
const offsetMinutesPart = String(Math.abs(offsetMinutes % 60)).padStart(2, '0');
const offsetSign = offsetMinutes > 0 ? '-' : '+'; // UTC is ahead of local if offset > 0

const formattedDate = `${year}-${month}-${day}T${hours}:${minutes}:${seconds}${offsetSign}${offsetHours}${offsetMinutesPart}`;

return formattedDate;

if (!Array.isArray(entitiesArray)) {
    console.error("Input is not an array.");
    return []; // Or throw an error
}

if (typeof datePropertyKey !== 'string' || !datePropertyKey.trim()) {
    console.error("Invalid or missing 'datePropertyKey' parameter. Please provide the name of the date property to sort by.");
    return entitiesArray; // Return original array or an empty one, or throw error
}

entitiesArray.sort((entityA, entityB) => {
    const dateStringA = entityA[datePropertyKey];
    const dateStringB = entityB[datePropertyKey];

    if (!dateStringA || !dateStringB) {
        console.warn(`One or both entities are missing the '${datePropertyKey}' property or its value is empty. Sorting might be inconsistent.`);
        // Handle missing properties:
        // If A has no date and B does, A goes to the end.
        if (!dateStringA && dateStringB) return 1;
        // If B has no date and A does, B goes to the end.
        if (dateStringA && !dateStringB) return -1;
        // If neither has a date, keep their relative order.
        return 0;
    }

    const dateA = new Date(dateStringA);
    const dateB = new Date(dateStringB);

    if (isNaN(dateA.getTime())) {
        console.warn(`Invalid date format for entity A's property '${datePropertyKey}': ${dateStringA}`);
        // Treat invalid date A as "older" or less important, so it goes to the end.
        if (isNaN(dateB.getTime())) return 0; // Both invalid, keep order
        return 1;
    }
    if (isNaN(dateB.getTime())) {
        console.warn(`Invalid date format for entity B's property '${datePropertyKey}': ${dateStringB}`);
        // Treat invalid date B as "older" or less important, so it goes to the end.
        return -1;
    }

    // For descending order (most recent first):
    // if dateB is more recent, its time value is larger.
    // dateB.getTime() - dateA.getTime() will be positive,
    // and sort will place entityA before entityB if the result is positive.
    // To get most recent (larger time value) first, we want b - a.
    return dateB.getTime() - dateA.getTime();
});

return entitiesArray; // sort() mutates the array, but returning it is common practice.

if (!Array.isArray(entities) || entities.length === 0) {
    console.warn("getMostRecentEntityId: Input 'entities' is not a valid array or is empty.");
    return null;
}

if (typeof entityIdKey !== 'string' || entityIdKey.trim() === '') {
    console.error("getMostRecentEntityId: 'entityIdKey' must be a non-empty string.");
    return null;
}

let mostRecentEntity = null;
let mostRecentDate = null;

for (let i = 0; i < entities.length; i++) {
    const currentEntity = entities[i];
    const currentDate = new Date(currentEntity.modifiedOn);

    if (currentEntity.hasOwnProperty(entityIdKey) && !isNaN(currentDate.getTime())) {
        mostRecentEntity = currentEntity;
        mostRecentDate = currentDate;
        break; // Found a valid starting point
    } else {
        console.warn(`getMostRecentEntityId: Skipping entity (index ${i}) due to missing/invalid '${entityIdKey}' or 'modifiedOn'.`);
    }
}

if (mostRecentEntity === null) {
    console.warn("getMostRecentEntityId: No valid entities found with 'modifiedOn' and specified 'entityIdKey'.");
    return null;
}

for (let i = 0; i < entities.length; i++) { // Iterate from beginning to ensure all are checked against the initial mostRecent
    const currentEntity = entities[i];
    const currentDate = new Date(currentEntity.modifiedOn);

    // Skip if current entity's date is invalid or if it lacks the ID key
    if (isNaN(currentDate.getTime()) || !currentEntity.hasOwnProperty(entityIdKey)) {
        continue;
    }

    // Compare dates: If the current entity is more recent
    if (currentDate.getTime() > mostRecentDate.getTime()) {
        mostRecentEntity = currentEntity;
        mostRecentDate = currentDate;
    }
}

return mostRecentEntity[entityIdKey];

entities.forEach(entity => { 
    let pipelineStageName;

    if (!entity.pipelineStageId) return;

    const pipelineStage = pipelineStages.find(pipelineStage => pipelineStage.pipelineStageId === entity.pipelineStageId);

    if (pipelineStage) {
        pipelineStageName = pipelineStage.name;
    }

    if (pipelineStageName) {
