    }
});

const {
    entityArray,
    labelKey,
    valueKey
} = options;

return entityArray.map(entity => {
    return {
        label: entity[labelKey],
        value: entity[valueKey]
    }
});

try {
    let { property, operation, value } = filter;

    if (!property || !operation) {
        return '';
    }

    const noValueOperations = ['isnull', 'isnotnull'];

    if (noValueOperations.includes(operation)) {
        return `${property}_${operation}`;
    }

    if (!value) {
        return '';
    }

    return `${property}_${operation}=${value}`;

} catch (error) {
    console.error('Error constructing filter string:', error);
    return null;
}

if (!Array.isArray(filters)) {
    return [];
}

const noValueOperations = ['isnull', 'isnotnull'];

return filters.filter(filter => {
    // Must have basic properties
    if (!filter || !filter.property || !filter.operation) {
        return false;
    }

    const isUnaryOp = noValueOperations.includes(filter.operation);

    if (isUnaryOp) {
        // Clear out value for unary operators
        filter.value = null;
        return true;
    }

    // Check for null, undefined, and empty strings
    const hasValue = filter.value != null && String(filter.value).trim() !== '';

    return hasValue;
});

if (!Array.isArray(sorts)) {
    return [];
}

return sorts.filter(({property, order}) => property && order);

if (!dateString) return '';

const date = new Date(dateString);
const now = new Date();

// Check for "Invalid Date"
if (isNaN(date.getTime())) return dateString;

const isToday = date.toDateString() === now.toDateString();

const yesterday = new Date();
yesterday.setDate(now.getDate() - 1);
const isYesterday = date.toDateString() === yesterday.toDateString();

const timeOptions = { hour: '2-digit', minute: '2-digit', hour12: true };

if (isToday) {
    return `Today at ${date.toLocaleTimeString([], timeOptions)}`;
}

if (isYesterday) {
    return `Yesterday at ${date.toLocaleTimeString([], timeOptions)}`;
}

// For older dates in the same year, we can omit the year to save space
const isSameYear = date.getFullYear() === now.getFullYear();
const dateOptions = {
    month: 'short',
    day: 'numeric',
    year: isSameYear ? undefined : 'numeric'
};

return date.toLocaleDateString([], dateOptions);

decimals = decimals ?? 2;

if (!bytes || bytes <= 0 || isNaN(bytes)) {
    return '0 Bytes';
}

const k = 1024;
const dm = decimals < 0 ? 0 : decimals;
const sizes = ['Bytes', 'KB', 'MB', 'GB', 'TB'];
const i = Math.floor(Math.log(bytes) / Math.log(k));
return `${parseFloat((bytes / Math.pow(k, i)).toFixed(dm))} ${sizes[i]}`;
